[
  {
    "alert_id": "EX4_001",
    "title": "Carbamazepine contraindicated with DTG",
    "message": "Guidelines list carbamazepine as a contraindication for DTG and state it decreases DTG levels by 30–70%. The patient started carbamazepine 2 weeks ago while on TLD. Viral load was suppressed (<50 copies/mL) in September 2025 but is now detectable at 1,240 copies/mL despite reported good adherence. This strongly suggests DTG levels have been reduced by carbamazepine, leading to virological failure. Guidelines recommend using valproic acid instead.",
    "issue_type": "drug_interaction",
    "severity": "critical",
    "recommended_action": "Stop carbamazepine and switch to valproic acid or another compatible antiepileptic. Repeat viral load after 3 months. If persistently detectable, proceed to genotype testing.",
    "citations": [
      {"page_number": 10, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p10_c1"},
      {"page_number": 49, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p49_c1"}
    ]
  },
  {
    "alert_id": "EX4_002",
    "title": "Carbamazepine toxicity with hyponatremia",
    "message": "The patient has carbamazepine level 14 mcg/mL (therapeutic 4–12), with symptoms of ataxia, nystagmus, and tremor. Hyponatremia (sodium 128 mmol/L) is also consistent with carbamazepine toxicity. The clinician plans dose reduction and repeat level, which is appropriate. Concurrent valproate may complicate management. ALT 68 U/L is mildly elevated; both carbamazepine and valproate can cause hepatotoxicity, though the elevation is modest.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Reduce carbamazepine dose as planned, repeat level and sodium. Monitor ALT. Consider neurology review for dual antiepileptic therapy and potential simplification.",
    "citations": []
  },
  {
    "alert_id": "EX4_003",
    "title": "Detectable viral load needs adherence and genotype plan",
    "message": "Guidelines define suppressed as ≤200 copies/mL. This patient's viral load rose from <50 to 1,240 copies/mL. The primary cause is likely the carbamazepine–DTG interaction reducing DTG levels. The clinician's plan does not address enhanced adherence counselling or a repeat viral load after correcting the interaction. Guidelines recommend genotype testing if viraemia persists after addressing adherence and interactions.",
    "issue_type": "plan_add",
    "severity": "high",
    "recommended_action": "After switching from carbamazepine, provide enhanced adherence counselling and repeat viral load in 3 months. If still detectable, perform genotype testing.",
    "citations": [
      {"page_number": 13, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p13_c2"},
      {"page_number": 12, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p12_c1"}
    ]
  }
]

